CREATE OR REPLACE VIEW `monto` AS select `d`.`detail_id` AS `detail_id`,`d`.`created` AS `created`,concat(`c`.`name`,' ',`c`.`business_name`) AS `customer`,concat(`c`.`discount`,'%') AS `discount`,sum(`d`.`sale_price` * `d`.`qty`) AS `sub_total`,sum(`d`.`sale_price` * `d`.`qty`) * `c`.`discount` / 100 AS `discount_total`,sum(`d`.`sale_price` * `d`.`qty`) - sum(`d`.`sale_price` * `d`.`qty`) * `c`.`discount` / 100 AS `total`,`d`.`catalog_id` AS `catalog_id`,`d`.`company_id` AS `company_id`,`cat`.`catalog_name` AS `catalog_name`,`d`.`product_id` AS `product_id`,`d`.`customer_id` AS `customer_id` from ((`detail` `d` join `customers` `c` on(`c`.`customer_id` = `d`.`customer_id`)) left join `catalog` `cat` on(`cat`.`catalog_id` = `d`.`catalog_id`)) group by `d`.`token_car`,`d`.`detail_id`,`d`.`created`,`c`.`name`,`c`.`business_name`,`c`.`discount`,`d`.`catalog_id`,`d`.`company_id`,`cat`.`catalog_name`,`d`.`product_id`,`d`.`customer_id`;
